    if 'read' in desc or 'sniff' in desc or 'listen' in desc:
        return 'Interception'
    elif 'alter' in desc or 'change' in desc or 'modify' in desc:
        return 'Modification'
    elif 'fake' in desc or 'forge' in desc or 'inject' in desc:
        return 'Fabrication'
    elif 'destroy' in desc or 'unavailable' in desc or 'down' in desc:
        return 'Interruption'
    return 'Unknown'

