import numpy as np

def calculate_psnr(original, watermarked):
    mse = np.mean((original.astype(float) - watermarked.astype(float)) ** 2)
    if mse == 0:
        return float('inf')
    max_pixel = 255.0
    psnr = 20 * np.log10(max_pixel / np.sqrt(mse))
    return psnr

def extract_secret_text(stego_text):
    binary_chars = []
    for char in stego_text:
        if char == '\u200B':
            binary_chars.append('0')
        elif char == '\u200C':
            binary_chars.append('1')
    binary_str = ''.join(binary_chars)
    # Convert binary back to ASCII chars
    chars = [chr(int(binary_str[i:i+8], 2)) for i in range(0, len(binary_str), 8)]
    return ''.join(chars)

