import numpy as np
def embed_coeff(coeffs, bit, r=5, c=5):
    if bit == 1:
        coeffs[r, c] = np.ceil(coeffs[r, c]) + 1
    else:
        coeffs[r, c] = np.floor(coeffs[r, c]) - 1
    return coeffs

